        let indirectDrawB = source.replacingOccurrences(of: "            bsr.s      DrawBufferB", with: "            jsr        (a0)")
        let indirectDrawA = source.replacingOccurrences(of: "            bsr.s      DrawBufferA", with: "            jsr        (a0)")

